            </p>
          )}
        </div>
      )}
      {!inbox.data && (
        <div
          role={inbox.error ? 'alert' : 'status'}
          className="flex flex-wrap items-center gap-3 border-b border-slate-100 bg-slate-50 px-4 py-2 text-xs text-slate-600"
        >
          {inbox.error || 'กำลังโหลดสถานะและผู้ดูแลแชท…'}
          {inbox.error && (
