          <input
            aria-label="ชื่อรายการพระเครื่อง / สินค้า"
            required
            maxLength={200}
            className={field}
            value={draft.itemName}
            disabled={busy || !!active || !!session.ended_at}
            onChange={(e) => setDraft((previous) => ({ ...previous, itemName: e.target.value }))}
            placeholder="เช่น พระสมเด็จ องค์ที่ 1"
          />
