            ชื่อนี้จะแสดงในบิลและข้อความแจ้งผู้ชนะ
          </span>
        </label>
        {(
          [
            {
              key: 'startPrice',
              label: 'ราคาเปิดประมูล (บาท)',
              help: 'ราคาที่ลูกค้าคนแรกเริ่มเคาะได้',
              min: '0.01',
            },
            {
              key: 'minStep',
              label: 'ราคาเคาะขั้นต่ำต่อครั้ง (บาท)',
              help: 'แต่ละครั้งที่พิมพ์ตรงคำดัก จะเพิ่มราคาตามจำนวนนี้',
              min: '0.01',
            },
            {
              key: 'shippingFee',
