          </select>
          <span className="mt-1 block text-xs font-normal text-slate-500">
            ใช้บัญชีนี้เมื่อเปิดบิลใหม่ บิลสะสมที่มีอยู่จะใช้บัญชีเดิมของลูกค้า
          </span>
        </label>
      </div>
      {active && (
        <p role="status" className="rounded-xl bg-white p-3 text-sm text-orange-800">
          กำลังประมูล: <b>{active.itemName}</b> · ผู้ขายนับปากเปล่า
          แล้วพิมพ์คำปิดรอบในนามเพจหรือบัญชี Facebook ของผู้เปิดรอบ
        </p>
      )}
      {session.ended_at && (
        <p className="text-sm text-slate-500">ไลฟ์นี้จบแล้ว เปิดดูบิลและจัดส่งได้ตามปกติ</p>
      )}
      {error && (
        <p role="alert" className="text-sm text-red-700">
          {error}
        </p>
      )}
      {notice && (
        <p role="status" className="text-sm text-emerald-700">
          {notice}
        </p>
      )}
      <div className="flex flex-wrap gap-3">
        <button
          className={`${orange} min-h-14 flex-1 text-base`}
          disabled={busy || !!active || !!session.ended_at || !draft.bankAccountId}
          type="submit"
        >
          {busy ? 'กำลังทำรายการ…' : 'เริ่มเปิดประมูลรอบนี้'}
        </button>
        <button
          type="button"
          className={`${button} min-h-14 bg-slate-100`}
          disabled={busy || !!session.ended_at}
          onClick={async () => {
            setError('')
            setNotice('')
            setBusy(true)
            try {
              if (active) {
                const result = await post('/api/live-cf/auction/close', {
                  auctionId: active.id,
                  cancel: true,
                })
                if (result.status === 'closed') {
                  setNotice('รอบนี้ปิดและบันทึกผู้ชนะแล้ว')
                  setActive(null)
                  onChanged()
                  return
                }
              }
              setActive(null)
              setDraft((previous) => ({
                ...previous,
                itemName: '',
                startPrice: '200',
                minStep: '20',
                shippingFee: '50',
              }))
              setNotice('ล้างรายการแล้ว พร้อมเปิดประมูลรายการใหม่')
              onChanged()
            } catch (cause) {
              setError(cause instanceof Error ? cause.message : 'ยกเลิกรายการไม่สำเร็จ')
            } finally {
              setBusy(false)
            }
          }}
        >
          ยกเลิก / ล้างรอบประมูล
        </button>
      </div>
    </form>
  )
}

files.components/live-cf/AuctionSessionAutomat:
'use client'
import { useRef, useState } from 'react'
import type { LiveSession } from '@/lib/features/commerce/live-session-types'
import {
  defaultSessionAutomation,
  displaySessionTemplate,
  normalizeBidKeyword,
  normalizeCloseKeyword,
  validSessionAutomation,
  type SessionAutomation,
} from '@/lib/features/commerce/session-automation'
import { LiveSwitch, LiveTemplateEditor } from './LiveReplyControls'
import type { AuctionDashboardOptions } from './AuctionSessionStart'
import { orange } from './session-ui'
import { AuctionKeywordEditor } from './AuctionKeywordEditor'

const variables = [
  { tag: '{ชื่อลูกค้า}', label: 'ชื่อลูกค้า', key: 'bidder_name' },
  { tag: '{รายการ}', label: 'รายการ', key: 'product_name' },
  { tag: '{ราคา}', label: 'ราคา', key: 'price' },
  { tag: '{ยอดรวมสะสม}', label: 'ยอดรวมสะสม', key: 'total' },
  { tag: '{เลขบัญชี}', label: 'เลขบัญชี', key: 'bank_account' },
]
function draftFrom(session: LiveSession, bankId?: string): SessionAutomation {
  const initial = session.auction_settings ?? defaultSessionAutomation(bankId)
  return {
    ...initial,
    keywords: initial.keywords ?? [],
    closeKeywords: initial.closeKeywords ?? [],
    countEnabled: false,
    heartCloses: false,
    bidText: displaySessionTemplate(initial.closeKeywords ? initial.bidText : initial.closeText),
    privateText: displaySessionTemplate(initial.privateText),
  }
}
export function AuctionSessionAutomation({
  tenantId,
  session,
  options,
  onSaved,
}: {
  tenantId: string
  session: LiveSession
  options: AuctionDashboardOptions
  onSaved: () => void
}) {
  const initial = draftFrom(session, options.bankAccounts[0]?.id)
  const [draft, setDraft] = useState(initial),
    [bidKeywords, setBidKeywords] = useState(initial.keywords),
    [closeKeywords, setCloseKeywords] = useState(initial.closeKeywords!)
  const [baseRevision, setBaseRevision] = useState(session.automation_revision ?? 0)
  const [busy, setBusy] = useState(false),
    [error, setError] = useState(''),
    [notice, setNotice] = useState('')
  const request = useRef({ key: '', id: '' })
  const disabled = busy || !!session.ended_at
  const settings = {
    ...draft,
    keywords: bidKeywords,
    closeKeywords,
    closeText: draft.bidText,
  }
  return (
    <form
      data-auction-automation
      className="space-y-5 rounded-xl border border-slate-200 p-4"
      onSubmit={async (event) => {
        event.preventDefault()
        if (!validSessionAutomation(settings)) return
        setBusy(true)
        setError('')
        setNotice('')
        const key = JSON.stringify({ settings, baseRevision })
        if (request.current.key !== key) request.current = { key, id: crypto.randomUUID() }
        try {
          const response = await fetch('/api/live-auction/session', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              tenantId,
              sessionId: session.id,
              action: 'settings',
              settings,
              revision: baseRevision,
              requestId: request.current.id,
            }),
            signal: AbortSignal.timeout(30000),
          })
          const result = await response.json()
          if (!response.ok) throw new Error(result.error || 'บันทึกคำดักไม่สำเร็จ')
          setBaseRevision(result.revision)
          request.current = { key: '', id: '' }
          setNotice('บันทึกแล้ว คำดักและข้อความนี้ใช้กับรอบปัจจุบันและรอบใหม่ในไลฟ์นี้')
          onSaved()
        } catch (cause) {
          setError(cause instanceof Error ? cause.message : 'บันทึกไม่สำเร็จ')
        } finally {
          setBusy(false)
        }
      }}
    >
      <h3 className="font-bold text-slate-900">ตั้งค่าคำดักและคำสั่งปิดรอบ</h3>
      <div className="grid gap-4 lg:grid-cols-2">
        <div className="min-w-0 space-y-2">
          <AuctionKeywordEditor
            key={'bid-' + baseRevision}
            label="คีย์เวิร์ดการดักคำ"
            kind="bid"
            keywords={bidKeywords}
            onChange={setBidKeywords}
            normalize={normalizeBidKeyword}
            disabled={disabled}
            onEdited={() => setNotice('')}
          />
          <p className="text-xs text-slate-500">
            ระหว่างเปิดรอบ คำนี้ใช้เคาะราคา เช่น 1 หลังปิดรอบ
            ผู้ชนะรอบล่าสุดพิมพ์คำนี้อีกครั้งเพื่อรับยอด · มีผลเมื่อกดบันทึก
          </p>
        </div>
        <div className="min-w-0 space-y-2">
          <AuctionKeywordEditor
            key={'close-' + baseRevision}
            label="คีย์เวิร์ดการปิดการประมูล"
            kind="close"
            keywords={closeKeywords}
            onChange={setCloseKeywords}
            normalize={normalizeCloseKeyword}
            disabled={disabled}
            onEdited={() => setNotice('')}
          />
          <p className="text-xs text-slate-500">
            เมื่อคอมเมนต์ของเพจหรือผู้ดูแลมีคำหรืออีโมจิที่เลือก เช่น ปิด ❌ หรือ 321 🛑
            ระบบจะปิดรอบและตัดสินผู้ชนะทันที คำสั่งของลูกค้าจะไม่ปิดรอบ · มีผลเมื่อกดบันทึก
          </p>
        </div>
      </div>
      <div className="grid gap-4 lg:grid-cols-2">
        <div className="space-y-3 rounded-xl bg-slate-50 p-4">
          <div className="flex items-center gap-3">
            <LiveSwitch
              checked={draft.publicReply}
              disabled={disabled}
              label="เปิดข้อความตอบกลับใต้คอมเมนต์"
              onChange={(publicReply) => setDraft((previous) => ({ ...previous, publicReply }))}
            />
            <h4 className="text-sm font-semibold">ข้อความตอบกลับใต้คอมเมนต์</h4>
          </div>
          <LiveTemplateEditor
            label="ข้อความตอบกลับใต้คอมเมนต์"
            value={draft.bidText}
            disabled={disabled || !draft.publicReply}
            variables={variables}
            maxLength={600}
            onChange={(bidText) => setDraft((previous) => ({ ...previous, bidText }))}
          />
          <p className="text-xs text-slate-500">
            ข้อความตอบกลับใต้คอมเมนต์ยืนยันของผู้ชนะรอบล่าสุดหน้าไลฟ์สด
            ระหว่างเคาะประมูลระบบจะจำผู้ขึ้นนำให้เงียบ ๆ
          </p>
        </div>
        <div className="space-y-3 rounded-xl bg-slate-50 p-4">
          <div className="flex items-center gap-3">
            <LiveSwitch
              checked={draft.privateReply}
              disabled={disabled}
              label="เปิดข้อความแจ้งยอดเข้าแชทส่วนตัว"
              onChange={(privateReply) => setDraft((previous) => ({ ...previous, privateReply }))}
            />
            <h4 className="text-sm font-semibold">ข้อความแจ้งยอดเข้าแชทส่วนตัว (Messenger)</h4>
          </div>
          <LiveTemplateEditor
            label="ข้อความแจ้งยอดเข้าแชทส่วนตัว (Messenger)"
            value={draft.privateText}
            disabled={disabled || !draft.privateReply}
            variables={variables}
            onChange={(privateText) => setDraft((previous) => ({ ...previous, privateText }))}
          />
          <p className="text-xs text-slate-500">
            เมื่อผู้ชนะรอบล่าสุดพิมพ์คีย์เวิร์ดยืนยัน จะส่งสรุปยอดสะสมและเลขบัญชีทาง Messenger
            รองรับตัวแปร {'{ชื่อลูกค้า}, {รายการ}, {ราคา}, {ยอดรวมสะสม}, {เลขบัญชี}'}{' '}
            ระบบแนบยอดค้างและลิงก์ชำระเงินให้ด้วย
          </p>
        </div>
      </div>
      {(session.automation_revision ?? 0) > baseRevision && (
        <p role="alert" className="text-sm text-amber-700">
          มีคนแก้ไขคำดักแล้ว{' '}
          <button
            type="button"
            className="underline"
            onClick={() => {
              const next = draftFrom(session, options.bankAccounts[0]?.id)
              setDraft(next)
              setBidKeywords(next.keywords)
              setCloseKeywords(next.closeKeywords!)
              setBaseRevision(session.automation_revision ?? 0)
            }}
          >
            ใช้ข้อมูลล่าสุด
          </button>
        </p>
      )}
      {!validSessionAutomation(settings) && !disabled && (
        <p className="text-xs text-orange-700">
          กรอกคำดักและคำปิดอย่างน้อยช่องละหนึ่งคำ คำต้องไม่ซ้ำกัน และใช้ตัวแปรที่กำหนดในข้อความ
        </p>
      )}
      {error && (
        <p role="alert" className="text-sm text-red-700">
          {error}
        </p>
      )}
      {notice && (
        <p role="status" className="text-sm text-emerald-700">
          {notice}
        </p>
      )}
      <button
        type="submit"
        className={orange}
        disabled={
          disabled ||
          !validSessionAutomation(settings) ||
          (session.automation_revision ?? 0) > baseRevision
        }
      >
        {session.ended_at ? 'ไลฟ์นี้จบแล้ว' : busy ? 'กำลังบันทึก…' : 'บันทึกคำดักและข้อความ'}
      </button>
    </form>
  )
}

files.components/live-cf/AuctionSessionCustome:
'use client'
import { useEffect, useMemo, useRef, useState } from 'react'
import { Download, MessagesSquare, Send } from 'lucide-react'
import {
  sessionCustomerRows,
  type SessionCustomerRow,
} from '@/lib/features/commerce/session-customer-rows'
import {
  sessionMoney as money,
  type SessionSnapshot,
  type SessionTab,
} from '@/lib/features/commerce/live-session-types'
import { SessionCustomerStatus } from './AuctionSessionSections'
import { button, orange } from './session-ui'

export function AuctionSessionCustomers({
  tenantId,
  data,
  onProof,
  onFollowup,
  onSnapshot,
}: {
  tenantId: string
  data: SessionSnapshot | null
  onProof: (tab: SessionTab) => void
  onFollowup: (tabIds: string[]) => void
  onSnapshot: (snapshot: SessionSnapshot) => void
}) {
  const rows = useMemo(() => sessionCustomerRows(data), [data])
  const [onlyMatched, setOnlyMatched] = useState(false),
    [selected, setSelected] = useState<string[]>([])
  const [busy, setBusy] = useState(false),
    [error, setError] = useState(''),
    [notice, setNotice] = useState('')
  const controller = useRef<AbortController | null>(null),
    all = useRef<HTMLInputElement>(null)
  useEffect(() => () => controller.current?.abort(), [])
  const visible = onlyMatched ? rows.filter((row) => row.matched) : rows
  const checkedRows = rows.filter((row) => selected.includes(row.id))
  const eligible = (checkedRows.length ? checkedRows : visible).flatMap((row) =>
    row.tab && Number(row.tab.remaining) > 0 ? [row.tab.id] : [],
  )
  const checked = visible.length > 0 && visible.every((row) => selected.includes(row.id))
  useEffect(() => {
    if (all.current)
      all.current.indeterminate = !checked && visible.some((row) => selected.includes(row.id))
  }, [checked, visible, selected])
  function toggle(id: string, checked: boolean) {
    setSelected((previous) =>
      checked ? [...new Set([...previous, id])] : previous.filter((value) => value !== id),
    )
  }
  async function loadSelected() {
    if (!data || !checkedRows.length || checkedRows.some((row) => !row.fbId)) return
    setBusy(true)
    setError('')
    setNotice('')
    const abort = new AbortController()
    controller.current?.abort()
    controller.current = abort
    try {
      const response = await fetch('/api/live-auction/session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tenantId,
          sessionId: data.session.id,
          action: 'load_customers',
          fbIds: checkedRows.map((row) => row.fbId),
          requestId: crypto.randomUUID(),
        }),
        signal: AbortSignal.any([abort.signal, AbortSignal.timeout(30000)]),
      })
      const result: SessionSnapshot & { error?: string } = await response.json()
      if (!response.ok) throw new Error(result.error || 'ดึงข้อมูลไม่สำเร็จ')
      if (result.session?.id !== data.session.id) throw new Error('ข้อมูลไม่ตรงกับไลฟ์ที่เลือก')
      if (!abort.signal.aborted) {
        onSnapshot(result)
        setNotice(`ดึงข้อมูล ${checkedRows.length} คนแล้ว`)
      }
    } catch (cause) {
      if (!abort.signal.aborted)
        setError(cause instanceof Error ? cause.message : 'ดึงข้อมูลไม่สำเร็จ')
    } finally {
      if (!abort.signal.aborted) setBusy(false)
    }
  }
  return (
    <section
      data-session-customers
      className="min-w-0 space-y-3 rounded-xl border border-slate-200 bg-white p-3 xl:col-span-7"
    >
      <header className="space-y-3">
        <h3 className="font-bold text-slate-900">รายชื่อลูกค้าและบิลสะสมในไลฟ์นี้</h3>
        <div className="flex flex-wrap items-center gap-2">
          <label className="flex min-h-10 items-center gap-2 text-xs">
            <input
              ref={all}
              type="checkbox"
              aria-label="เลือกลูกค้าทั้งหมดที่แสดง"
              checked={checked}
              disabled={!visible.length || busy}
              onChange={(e) => setSelected(e.target.checked ? visible.map((row) => row.id) : [])}
            />
            เลือกทั้งหมด
          </label>
          <button
            type="button"
            className={`${orange} inline-flex shrink-0 items-center gap-1.5 whitespace-nowrap`}
            disabled={!eligible.length || busy}
            onClick={() => onFollowup(eligible)}
          >
            <Send className="h-4 w-4" /> ตามยอดค้างชำระ
          </button>
          <button
            type="button"
            className={`${button} inline-flex shrink-0 items-center gap-1.5 whitespace-nowrap`}
            disabled={
              busy ||
              !checkedRows.length ||
              checkedRows.length > 500 ||
              checkedRows.some((row) => !row.fbId)
            }
            onClick={() => void loadSelected()}
          >
            <Download className="h-4 w-4" />
            {busy ? 'กำลังดึงข้อมูล…' : 'ดึงข้อมูลคนที่เลือก'}
          </button>
          <label className="flex min-h-10 items-center gap-2 text-xs">
            <input
              type="checkbox"
              checked={onlyMatched}
              onChange={(e) => {
                setOnlyMatched(e.target.checked)
                setSelected([])
              }}
              aria-label="เฉพาะคนตรงคำดัก"
            />
            เฉพาะคนตรงคำดัก
          </label>
          <p className="text-[10px] text-slate-500">
            เลือกเพื่อแสดงเฉพาะลูกค้าที่พิมพ์ตรงคำดักของไลฟ์นี้
          </p>
        </div>
        <SessionCustomerStatus data={data} />
        <p className="text-[10px] text-slate-500">
          ส่งตามยอดไม่เกิน 12 ข้อความต่อนาทีต่อเพจ โดยตรวจยอดค้างล่าสุดก่อนส่ง
        </p>
        <p className="text-xs text-slate-500">
          แสดง {visible.length} คน · เลือก {checkedRows.length} คน · คลิกยอดเงินเพื่อตรวจและปรับยอด
        </p>
      </header>
      {error && (
        <p role="alert" className="text-sm text-red-700">
          {error}
        </p>
      )}
      {notice && (
        <p role="status" className="text-sm text-emerald-700">
          {notice}
        </p>
      )}
      <div className="overflow-x-auto rounded-xl border border-slate-200">
        <table
          className="w-full min-w-[520px] text-left text-xs"
          aria-label="รายชื่อลูกค้าและบิลสะสม"
        >
          <thead className="bg-slate-50 text-slate-500">
            <tr>
              <th className="w-8 p-2">
                <span className="sr-only">เลือก</span>
              </th>
              {['ชื่อ', 'ยอดซื้อ', 'สถานะโอน', 'คอมเมนต์ล่าสุด', 'แชท', 'เวลา'].map(
                (label) => (
                  <th key={label} className="p-2">
                    {label}
                  </th>
                ),
              )}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {visible.map((row) => (
              <tr
                key={row.id}
                data-customer-row={row.id}
                className={selected.includes(row.id) ? 'bg-orange-50/40' : ''}
              >
                <td className="p-2 align-top">
                  <input
                    type="checkbox"
                    aria-label={`เลือกลูกค้า ${row.name}`}
                    checked={selected.includes(row.id)}
                    disabled={busy}
                    onChange={(e) => toggle(row.id, e.target.checked)}
                  />
                </td>
                <td className="max-w-36 break-words p-2 align-top">
                  <b>{row.name}</b>
                </td>
                <td className="max-w-48 p-2 align-top">
                  {row.tab ? (
                    <>
                      <button
                        type="button"
                        className="font-bold tabular-nums text-orange-600 underline underline-offset-4"
                        aria-label={`ดูที่มาของยอด ${row.name}`}
                        onClick={() => onProof(row.tab!)}
                      >
                        {money(row.tab.total)} ฿
                      </button>
                      <span className="mt-1 block text-[10px] text-slate-500">
                        📣 ชนะประมูล {row.tab.items.filter((item) =>
                          item.name.startsWith('[ประมูล]') ||
                          data?.rounds.some((round) => round.orderId === item.orderId),
                        ).length} รายการ
                      </span>
                    </>
                  ) : (
                    <span className="text-slate-400">ยังไม่มีบิล</span>
                  )}
                </td>
                <td className="p-2 align-top">
                  <div className="space-y-1">
                    {row.tab ? (
                      <>
                        {Number(row.tab.paid) > 0 && (
                          <span className="block rounded-lg bg-emerald-50 px-2 py-1.5 font-semibold tabular-nums text-emerald-700">
                            {Number(row.tab.remaining) <= 0
                              ? `โอนครบแล้ว ${money(row.tab.paid)} บาท`
                              : `โอนแล้ว ${money(row.tab.paid)} บาท`}
                          </span>
                        )}
                        {Number(row.tab.remaining) > 0 && Number(row.tab.paid) > 0 && (
                          <span className="block rounded-lg bg-red-50 px-2 py-1.5 font-semibold tabular-nums text-red-700">
                            โอนขาด {money(row.tab.remaining)} ฿
                          </span>
                        )}
                        {Number(row.tab.paid) <= 0 && Number(row.tab.remaining) > 0 && (
                          <span className="block rounded-lg bg-orange-50 px-2 py-1.5 font-semibold text-orange-700">
                            ยังไม่โอน
                            <span className="block text-[10px]">
                              ขาด {money(row.tab.remaining)} ฿
                            </span>
