                      normalize={normalizeCloseKeyword}
                      disabled={disabled}
                    />
                  </div>
                  <p className="text-xs leading-relaxed text-slate-500">
                    ขณะเปิดรอบ คำดักใช้เคาะราคา หลังปิดรอบ ผู้ชนะพิมพ์คำเดิมอีกครั้งเพื่อรับยอด
                  </p>
                </div>
                <div className="min-w-0 space-y-4 rounded-xl border border-slate-200 bg-white p-3 sm:p-4 [&_textarea]:!rounded-lg [&_textarea]:!border-slate-300 [&_textarea]:!px-3 [&_textarea]:!py-2.5">
                  <h3 className="flex items-center gap-2 text-sm font-semibold text-slate-900">
                    <Bot aria-hidden="true" className="h-5 w-5 text-orange-500" />
                    ระบบตอบกลับอัตโนมัติ
                  </h3>
                  {(
                    [
                      {
                        key: 'bidText',
                        toggle: 'publicReply',
                        label: 'Public Reply ใต้คอมเมนต์',
                        maxLength: 600,
                      },
                      {
                        key: 'privateText',
                        toggle: 'privateReply',
                        label: 'Private Reply เข้า Inbox',
                        maxLength: 1500,
                      },
                    ] as const
                  ).map(({ key, toggle, label, maxLength }) => (
                    <div key={key} className="min-w-0 space-y-2 border-t border-slate-100 pt-4">
                      <div className="flex items-center justify-between gap-3">
                        <h3 className="text-sm font-semibold text-slate-800">{label}</h3>
                        <LiveSwitch
                          checked={draft.settings[toggle]}
                          onChange={(value) =>
                            edit({ settings: { ...draft.settings, [toggle]: value } })
                          }
                          label={`เปิด ${label}`}
                          disabled={disabled}
                        />
                      </div>
                      <LiveTemplateEditor
                        label={label}
                        value={draft.settings[key]}
                        onChange={(value) =>
                          edit({ settings: { ...draft.settings, [key]: value } })
                        }
                        variables={variables}
                        maxLength={maxLength}
                        disabled={disabled || !draft.settings[toggle]}
                      />
                    </div>
                  ))}
                  <div className="space-y-2 rounded-xl border border-orange-100 bg-orange-50/60 p-3">
                    <div className="flex items-start justify-between gap-3">
                      <h3 className="min-w-0 text-sm font-semibold leading-relaxed text-slate-800">
                        แยกส่งแจ้งยอดชิ้นล่าสุด + บิลรวมสะสมอัตโนมัติ
                      </h3>
                      <LiveSwitch
                        checked={draft.settings.auto_accumulate_summary ?? true}
                        onChange={(value) =>
                          edit({ settings: { ...draft.settings, auto_accumulate_summary: value } })
                        }
                        label="แยกส่งแจ้งยอดชิ้นล่าสุด + บิลรวมสะสมอัตโนมัติ"
                        disabled={disabled}
                      />
                    </div>
                    <p className="text-xs leading-relaxed text-slate-600">
                      ส่งข้อความแรกแจ้งยอดชิ้นที่เพิ่งปิด
                      แล้วส่งข้อความที่สองสรุปบิลรวมสะสมตามหลังทันที
                    </p>
                    <p className="text-xs leading-relaxed text-slate-500">
                      หากหน้าต่างแชตยังไม่เปิด ข้อความสรุปจะรอให้ลูกค้าตอบกลับใน Inbox ก่อน
                    </p>
                  </div>
                  <label className="block text-sm font-semibold text-slate-800">
                    <span className="flex items-center gap-2">
                      <Landmark aria-hidden="true" className="h-4 w-4 text-orange-500" />
                      บัญชีธนาคารรับเงิน
                    </span>
                    <select
                      aria-label="บัญชีธนาคารรับเงิน"
                      className={`${field} !mt-2 !rounded-lg !border-slate-300 !px-3 !py-2.5`}
                      required
                      disabled={locked}
                      value={draft.settings.bankAccountId}
                      onChange={(e) =>
                        edit({ settings: { ...draft.settings, bankAccountId: e.target.value } })
                      }
                    >
                      <option value="">เลือกบัญชีรับเงิน</option>
                      {options.bankAccounts.map((bank) => (
                        <option key={bank.id} value={bank.id}>
                          {bank.bank_code} · {bank.account_number}
                        </option>
                      ))}
                    </select>
                  </label>
                </div>
              </div>
            </section>
          </div>
          <div className="flex flex-col items-center gap-3 rounded-2xl border border-orange-100 bg-orange-50/60 p-4 text-center sm:p-5">
            <div className="text-sm leading-relaxed text-slate-600">
              {base?.session?.ended_at
                ? 'ไลฟ์นี้จบแล้ว เลือกไลฟ์ใหม่เพื่อเริ่มประมูล'
                : base?.round?.status === 'active' && !base.preferencesOnly
                  ? `กำลังประมูล: ${base.round.item_name}`
                  : 'บันทึกเงื่อนไขและคำดักทั้งหมดพร้อมเปิดรอบในครั้งเดียว'}
            </div>
            <button
              type="submit"
              className={`${orange} min-h-12 w-full justify-center !rounded-lg px-6 text-base font-bold shadow-sm sm:max-w-md`}
              disabled={disabled || !draft.pageId || !draft.livePostId}
            >
              {busy ? 'กำลังบันทึก…' : 'บันทึกและเริ่มประมูล'}
            </button>
          </div>
        </section>
      )}
    </form>
  )
}

files.components/live-cf/LiveAuctionPanel.tsx:
'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { Gavel, Radio, Trophy } from 'lucide-react'
import type { Auction, AuctionBid } from '@/lib/features/commerce/auction-types'
import type { LiveSession } from '@/lib/features/commerce/live-session-types'
import { LiveSourcePicker, type LiveSourcePage } from './LiveSourcePicker'
import { LiveSwitch, LiveTemplateEditor, ReceivingBankPicker } from './LiveReplyControls'
import { LiveAuctionTimer } from './LiveAuctionTimer'
import {
  AUCTION_PRIVATE_TEMPLATE,
  AUCTION_BID_TEMPLATE,
  AUCTION_CLOSE_TEMPLATE,
  displayAuctionTemplate,
  auctionVariables,
  auctionPublicVariables,
} from '@/lib/features/commerce/auction-templates'

type Delivery = { channel: string; status: string; error_code: string | null }
type Snapshot = {
  selectedAuctionId?: string
  auctions: Auction[]
  bids: AuctionBid[]
  deliveries: Delivery[]
}
const field =
  'mt-1 w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm focus:border-orange-400 focus:outline-none focus:ring-2 focus:ring-orange-100'
const money = (value: number) => Number(value).toLocaleString('th-TH', { maximumFractionDigits: 2 })
const statusLabel: Record<string, string> = {
  accepted: 'รับราคาแล้ว',
  already_opened: 'มีผู้เปิดแล้ว',
  too_low: 'ต่ำกว่าขั้นต่ำ',
  closed: 'ปิดประมูลแล้ว',
  count: 'ผู้ขายนับเคาะ',
  stale: 'คอมเมนต์ก่อนเปิดรอบ',
}

export function LiveAuctionPanel({
  tenantId,
  bankAccounts,
  pages = [],
  active = true,
  onSessionEnded,
  session,
}: {
  tenantId: string
  bankAccounts: { id: string; bank_code: string; account_number: string }[]
  pages?: LiveSourcePage[]
  active?: boolean
  onSessionEnded?: () => void
  session?: LiveSession
}) {
  const [snapshot, setSnapshot] = useState<Snapshot>({ auctions: [], bids: [], deliveries: [] })
  const [selectedId, setSelectedId] = useState('')
  const [error, setError] = useState('')
  const [loadError, setLoadError] = useState('')
  const [notice, setNotice] = useState('')
  const [lastUpdated, setLastUpdated] = useState<string | null>(null)
  const requestVersion = useRef(0)
  const initialized = useRef(false)
  const [busy, setBusy] = useState(false)
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(true)
  const [draft, setDraft] = useState({
    itemName: '',
    pageId: pages[0]?.id ?? '',
    livePostId: '',
    startPrice: '200',
    minStep: '20',
    shippingFee: '50',
    bankAccountId: bankAccounts[0]?.id ?? '',
    hostIds: '',
    privateReply: true,
    publicReply: true,
    privateText: displayAuctionTemplate(AUCTION_PRIVATE_TEMPLATE),
    bidText: displayAuctionTemplate(AUCTION_BID_TEMPLATE),
    closeText: displayAuctionTemplate(AUCTION_CLOSE_TEMPLATE),
  })
  const sessionPageId = session?.page_id
  const sessionPostId = session?.live_post_id
  const sessionSettings = session?.auction_settings
  useEffect(() => {
    if (!sessionPageId || !sessionPostId) return
    setDraft((previous) => ({
      ...previous,
      pageId: sessionPageId,
      livePostId: sessionPostId,
      ...(sessionSettings
        ? {
            bankAccountId: sessionSettings.bankAccountId,
            privateReply: sessionSettings.privateReply,
            publicReply: sessionSettings.publicReply,
            privateText: sessionSettings.privateText,
            bidText: sessionSettings.bidText,
            closeText: sessionSettings.closeText,
          }
        : {}),
    }))
  }, [sessionPageId, sessionPostId, sessionSettings])
  const refresh = useCallback(
    async (signal?: AbortSignal) => {
      const version = ++requestVersion.current
      try {
        const params = new URLSearchParams({ tenantId })
        if (sessionPageId && sessionPostId) {
          params.set('pageId', sessionPageId)
          params.set('livePostId', sessionPostId)
        }
        if (selectedId) params.set('id', selectedId)
        const response = await fetch(`/api/live-cf/auction?${params}`, {
          cache: 'no-store',
          signal,
        })
        const data = await response.json()
        if (!response.ok) throw new Error(data.error || 'โหลดข้อมูลประมูลไม่สำเร็จ')
        if (!signal?.aborted && version === requestVersion.current) {
          setSnapshot(data)
          if (!initialized.current) {
            initialized.current = true
            if (data.auctions?.some((a: Auction) => a.status === 'active')) setShowForm(false)
          }
          setLoadError('')
          setLastUpdated(new Date().toLocaleTimeString('th-TH', { timeZone: 'Asia/Bangkok' }))
        }
      } catch (cause) {
        if (!signal?.aborted && version === requestVersion.current)
          setLoadError(cause instanceof Error ? cause.message : 'โหลดข้อมูลไม่สำเร็จ')
      } finally {
        if (!signal?.aborted && version === requestVersion.current) setLoading(false)
      }
    },
    [tenantId, selectedId, sessionPageId, sessionPostId],
  )

  useEffect(() => {
    if (!active) return
    const controller = new AbortController()
    let timer: ReturnType<typeof setTimeout>
    let polling = false
    const poll = async () => {
      if (polling) return
      polling = true
      if (!document.hidden) await refresh(controller.signal)
      polling = false
      if (!controller.signal.aborted) timer = setTimeout(poll, 3000)
    }
    void poll()
    const onVisible = () => {
      if (!document.hidden) {
        clearTimeout(timer)
        void poll()
      }
    }
    document.addEventListener('visibilitychange', onVisible)
    return () => {
      controller.abort()
      clearTimeout(timer)
      document.removeEventListener('visibilitychange', onVisible)
    }
  }, [refresh, active])

  const auction =
    snapshot.auctions.find((a) => a.id === (selectedId || snapshot.selectedAuctionId)) ??
    (!selectedId ? snapshot.auctions[0] : undefined)
  async function mutate(path: string, input: Record<string, unknown>) {
    setBusy(true)
    setError('')
    setNotice('')
    try {
      const response = await fetch(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, ...input }),
      })
      const data = await response.json()
      if (!response.ok) throw new Error(data.error || 'ดำเนินการไม่สำเร็จ')
      if (typeof data.message === 'string') setNotice(data.message)
      if (data.id) {
        ++requestVersion.current
        setLoading(true)
        setSnapshot((previous) => ({ ...previous, bids: [], deliveries: [] }))
        setSelectedId(data.id)
        setShowForm(false)
      } else await refresh()
      if (input.action === 'end_live') onSessionEnded?.()
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'ดำเนินการไม่สำเร็จ')
    } finally {
      setBusy(false)
    }
  }

  return (
    <section
      data-auction-panel
      className="mb-8 shrink-0 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"
      aria-label="ระบบประมูลสด"
    >
      <header className="flex flex-wrap items-center justify-between gap-4 border-b border-slate-100 bg-orange-50/60 p-5">
        <div className="flex items-center gap-3">
          <span className="rounded-xl bg-orange-500 p-2.5 text-white">
            <Gavel className="h-5 w-5" />
          </span>
          <div>
            <h1 className="text-lg font-bold text-slate-900">ห้องควบคุมการประมูลสด</h1>
            <p className="text-sm text-slate-500">
              ปิดรอบอัตโนมัติเมื่อครบเวลา • รอบใหม่เริ่มต้น 5 นาที
            </p>
          </div>
        </div>
        <button
          type="button"
          disabled={!!session?.ended_at}
          onClick={() => setShowForm(!showForm)}
          className="rounded-xl bg-slate-900 px-4 py-2 text-sm font-semibold text-white"
        >
          {showForm ? 'ซ่อนแบบฟอร์ม' : 'เปิดรายการใหม่'}
        </button>
      </header>
      {auction && (
        <LiveAuctionTimer
          key={auction.id}
          tenantId={tenantId}
          auctionId={auction.id}
          onResolved={() => {
            void refresh()
          }}
        />
      )}
      <div className="space-y-5 p-5">
        <p className="text-xs text-slate-500" aria-live="polite">
          อัปเดตอัตโนมัติทุก 3 วินาที{lastUpdated ? ` • ล่าสุด ${lastUpdated}` : ''}
        </p>
        {(error || loadError) && (
          <p role="alert" className="rounded-xl bg-red-50 p-3 text-sm text-red-700">
            {error || loadError}
          </p>
        )}
        {notice && (
          <p role="status" className="rounded-xl bg-emerald-50 p-3 text-sm text-emerald-800">
            {notice}
          </p>
        )}
        {!session && (
          <div className="sm:col-span-2 lg:col-span-3">
            <LiveSourcePicker
              pages={pages}
              pageId={showForm ? draft.pageId : (auction?.page_id ?? draft.pageId)}
              livePostId={showForm ? draft.livePostId : (auction?.live_post_id ?? draft.livePostId)}
              active={active}
              disabled={busy || !showForm}
              onPageChange={(pageId) =>
                setDraft((previous) => ({ ...previous, pageId, livePostId: '' }))
              }
              onLiveChange={(livePostId) => setDraft((previous) => ({ ...previous, livePostId }))}
            />
          </div>
        )}
        {showForm && !session?.ended_at && (
          <form
            onSubmit={(event) => {
              event.preventDefault()
              void mutate('/api/live-cf/auction', {
                ...draft,
                startPrice: Number(draft.startPrice),
                minStep: Number(draft.minStep),
                shippingFee: Number(draft.shippingFee),
                hostIds: draft.hostIds.split(/[\s,]+/).filter(Boolean),
              })
            }}
            className="grid gap-4 rounded-xl border border-slate-200 bg-slate-50 p-4 sm:grid-cols-2 lg:grid-cols-3"
          >
            <label className="text-sm font-medium">
              ชื่อรายการ
              <input
                required
                maxLength={200}
                className={field}
                value={draft.itemName}
                onChange={(e) => setDraft({ ...draft, itemName: e.target.value })}
                placeholder="เหรียญรุ่น 1"
              />
            </label>
            {(
              [
                { key: 'startPrice', label: 'ราคาเปิด (บาท)', min: '0.01' },
                { key: 'minStep', label: 'สเต็ปขั้นต่ำ (บาท)', min: '0.01' },
                { key: 'shippingFee', label: 'ค่าจัดส่ง (บาท)', min: '0' },
              ] as const
            ).map(({ key, label, min }) => (
              <label key={key} className="text-sm font-medium">
                {label}
                <input
                  type="number"
                  required
                  min={min}
                  max={key === 'shippingFee' ? 999999 : 999999999}
                  step="0.01"
                  className={field}
                  value={draft[key]}
                  onChange={(e) => setDraft({ ...draft, [key]: e.target.value })}
                />
              </label>
            ))}
            {!session && (
              <div className="max-w-lg">
                <ReceivingBankPicker
                  accounts={bankAccounts}
                  value={draft.bankAccountId}
                  required
                  disabled={busy}
                  onChange={(bankAccountId) =>
                    setDraft((previous) => ({ ...previous, bankAccountId }))
                  }
                />
              </div>
            )}
            <label className="text-sm font-medium sm:col-span-2">
              Facebook ID ผู้ช่วยคุมประมูล (ถ้ามี)
              <input
                className={field}
                value={draft.hostIds}
                onChange={(e) => setDraft({ ...draft, hostIds: e.target.value })}
                placeholder="คั่นด้วยจุลภาค • เพจที่เชื่อมต่อมีสิทธิ์อยู่แล้ว"
              />
              <span className="mt-1 block text-xs text-slate-500">
                ID ที่เพิ่มมีสิทธิ์สั่งปิดผ่านคอมเมนต์ได้
              </span>
            </label>
            {!session && (
              <div className="space-y-5 rounded-xl border border-slate-200 bg-white p-4 sm:col-span-2 lg:col-span-3">
                <h2 className="font-bold text-slate-900">ข้อความตอบกลับอัตโนมัติ</h2>
                <div className="space-y-3">
                  <div className="flex items-start gap-3">
                    <LiveSwitch
                      checked={draft.privateReply}
                      disabled={busy}
                      label="ส่งสรุปยอดเข้า Messenger"
                      onChange={(privateReply) =>
                        setDraft((previous) => ({ ...previous, privateReply }))
                      }
                    />
                    <span className="text-sm font-semibold">
                      ส่งสรุปยอดและลิงก์ชำระเงินเข้ากล่องข้อความ Facebook (Messenger)
                    </span>
                  </div>
                  {draft.privateReply && (
                    <LiveTemplateEditor
                      label="ข้อความสรุปยอดผู้ชนะประมูล"
                      value={draft.privateText}
                      disabled={busy}
                      variables={auctionVariables}
                      onChange={(privateText) =>
                        setDraft((previous) => ({ ...previous, privateText }))
                      }
                    />
                  )}
                  <p className="text-xs text-slate-500">
                    ยอดชำระ คือยอดค้างสุทธิของบิลสะสมหลังหักยอดโอนที่ตรวจสอบแล้ว
                    ระบบแนบสรุปยอดและลิงก์แนบสลิปให้เสมอ ข้อความยาวจะย่อให้เหมาะกับปุ่ม Messenger
                    โดยคงยอดเงินและลิงก์บิลครบถ้วน
                  </p>
                </div>
                <div className="space-y-3 border-t border-slate-100 pt-4">
                  <div className="flex items-center gap-3">
                    <LiveSwitch
                      checked={draft.publicReply}
                      disabled={busy}
                      label="ตอบกลับใต้คอมเมนต์ประมูล"
                      onChange={(publicReply) =>
                        setDraft((previous) => ({ ...previous, publicReply }))
                      }
                    />
                    <span className="text-sm font-semibold">ตอบกลับใต้คอมเมนต์</span>
                  </div>
                  {draft.publicReply && (
                    <div className="grid gap-4 lg:grid-cols-2">
                      <div>
                        <p className="text-sm font-medium">ยืนยันผู้เปิดราคา / ผู้นำล่าสุด</p>
                        <LiveTemplateEditor
                          label="ข้อความยืนยันผู้นำประมูล"
                          value={draft.bidText}
                          variables={auctionPublicVariables}
                          rows={3}
                          maxLength={600}
                          disabled={busy}
                          onChange={(bidText) => setDraft((previous) => ({ ...previous, bidText }))}
                        />
                      </div>
                      <div>
                        <p className="text-sm font-medium">ประกาศผู้ชนะเมื่อปิดประมูล (❌)</p>
                        <LiveTemplateEditor
                          label="ข้อความประกาศผู้ชนะประมูล"
                          value={draft.closeText}
                          variables={auctionPublicVariables}
                          rows={3}
                          maxLength={600}
                          disabled={busy}
                          onChange={(closeText) =>
                            setDraft((previous) => ({ ...previous, closeText }))
                          }
                        />
                      </div>
                    </div>
                  )}
                </div>
                <p className="text-xs text-slate-500">
                  ใช้บัญชีนี้ในบิลสะสมและหน้าชำระเงิน คิดค่าจัดส่งครั้งเดียวต่อรอบไลฟ์
                </p>
              </div>
            )}
            <p className="text-sm text-slate-500 sm:col-span-2">
              ลูกค้าพิมพ์ “เปิดให้ 10 ลุ้น” เพื่อเปิดตามราคาตั้งต้น หรือ “1” / “+1”
              เพื่อเพิ่มหนึ่งสเต็ป ระหว่างรอบนี้คอมเมนต์ของไลฟ์จะเข้าระบบประมูล
            </p>
            <button
              disabled={busy || !draft.pageId || !draft.livePostId}
              className="rounded-xl bg-orange-500 px-4 py-3 font-semibold text-white disabled:opacity-50"
            >
              {busy ? 'กำลังบันทึก…' : 'เริ่มเปิดประมูลรายการนี้'}
            </button>
          </form>
        )}
        {loading ? (
          <p className="text-sm text-slate-500">กำลังโหลดรายการ…</p>
        ) : !auction ? (
          <p className="py-4 text-sm text-slate-500">
            ยังไม่มีรายการประมูล กดเปิดรายการใหม่เพื่อเริ่มต้น
          </p>
        ) : (
          <>
            <label className="block max-w-lg text-sm font-medium">
              รายการประมูล
