function sessionLabel(session: LiveSession) {
  const date = new Date(session.created_at)
  if (!Number.isFinite(date.getTime()))
    return session.ended_at ? '⚪ สิ้นสุดแล้ว • ไม่ระบุวันที่' : '🔴 สด • ไม่ระบุเวลา'

  const time = date.toLocaleTimeString('th-TH', {
    timeZone: 'Asia/Bangkok',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  })
  if (session.ended_at) {
    const day = date.toLocaleDateString('th-TH-u-ca-buddhist', {
      timeZone: 'Asia/Bangkok',
      day: '2-digit',
      month: '2-digit',
      year: '2-digit',
    })
    return `⚪ สิ้นสุดแล้ว • ${day} (${time} น.)`
  }

  const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Bangkok' })
  return today.format(date) === today.format(new Date())
    ? `🔴 สด • วันนี้ ${time} น.`
    : `🔴 สด • ${date.toLocaleDateString('th-TH-u-ca-buddhist', {
        timeZone: 'Asia/Bangkok',
        day: '2-digit',
        month: '2-digit',
        year: '2-digit',
      })} (${time} น.)`
}

export function LiveSessionDashboard({
  tenantId,
  active = true,
  auction,
}: {
  tenantId: string
  active?: boolean
  auction?: AuctionDashboardOptions
}) {
  const [sessions, setSessions] = useState<LiveSession[]>([])
  const [sessionId, setSessionId] = useState('')
  const [snapshot, setSnapshot] = useState<SessionSnapshot | null>(null)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [skippedAuthors, setSkippedAuthors] = useState(0)
  const [loading, setLoading] = useState(true)
  const [version, setVersion] = useState(0)
  const [updated, setUpdated] = useState('')
  const [selected, setSelected] = useState<string[]>([])
  const [modal, setModal] = useState<
    | { kind: 'proof'; tab: SessionTab }
    | { kind: 'winner'; round: SessionRound }
    | { kind: 'followup' }
    | null
  >(null)
  const sequence = useRef(0)
  const allInOne = !!auction
  useEffect(() => {
    const id = new URL(location.href).searchParams.get('session')
    if (id && /^[a-f0-9-]{36}$/i.test(id)) setSessionId(id)
  }, [])
  useEffect(() => {
    if (!active) return
    const controller = new AbortController()
    let timer: ReturnType<typeof setTimeout>
    let pending = false
    const run = async () => {
      if (pending || controller.signal.aborted) return
      pending = true
      const request = ++sequence.current
      try {
        if (!document.hidden) {
          const list = await read(
            `/api/live-cf/sessions?${new URLSearchParams({ tenantId })}`,
            controller.signal,
          )
          if (controller.signal.aborted || request !== sequence.current) return
          setSessions(list.sessions)
          const chosen = sessionId || list.sessions[0]?.id
          if (chosen && !sessionId) {
            setSessionId(chosen)
            return
          }
          if (chosen) {
            const result: SessionSnapshot = await read(
              `${allInOne ? '/api/live-auction/session' : '/api/live-cf/sessions'}?${new URLSearchParams({ tenantId, sessionId: chosen })}`,
              controller.signal,
            )
            if (!controller.signal.aborted && request === sequence.current) {
              setSnapshot(result)
              setUpdated(new Date().toLocaleTimeString('th-TH', { timeZone: 'Asia/Bangkok' }))
            }
          }
          if (!controller.signal.aborted) setError('')
        }
      } catch (cause) {
        // Optional dashboard reads must not cover the auction setup with schema alerts.
        if (!controller.signal.aborted && !allInOne)
          setError(cause instanceof Error ? cause.message : 'โหลดข้อมูลไม่สำเร็จ')
      } finally {
        pending = false
        if (!controller.signal.aborted) {
          setLoading(false)
          timer = setTimeout(run, 5000)
        }
      }
    }
    const visible = () => {
      if (!document.hidden) {
        clearTimeout(timer)
        void run()
      }
    }
    void run()
    document.addEventListener('visibilitychange', visible)
    return () => {
      controller.abort()
      clearTimeout(timer)
      document.removeEventListener('visibilitychange', visible)
    }
  }, [tenantId, active, sessionId, version, allInOne])
  const post = useCallback<Post>(
    async (input, requestId) => {
      const response = await fetch('/api/live-cf/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, sessionId, requestId, ...input }),
        signal: AbortSignal.timeout(45000),
      })
      const result = await response.json()
      if (!response.ok) throw new Error(result.error || 'บันทึกไม่สำเร็จ')
      setVersion((previous) => previous + 1)
      setNotice(result.message || 'บันทึกแล้ว ยอดจะอัปเดตจากบิลล่าสุด')
      return result
    },
    [tenantId, sessionId],
  )
  function choose(id: string) {
    setSkippedAuthors(0)
    setSessionId(id)
    setSnapshot(null)
    setSelected([])
    setModal(null)
    setError('')
    setLoading(true)
    const url = new URL(location.href)
    url.searchParams.set('session', id)
    history.replaceState(null, '', url)
  }
  const data = snapshot?.session.id === sessionId ? snapshot : null
  const finance = data ? (
