          ['คอมเมนต์ตรงคำดัก', data.metrics.matched.toLocaleString('th-TH')],
          ['จำนวนคนคอมเมนต์', `${data.metrics.commenters.toLocaleString('th-TH')} คน`],
          ['สลิปที่ตรวจผ่าน', `${data.metrics.slips.toLocaleString('th-TH')} สลิป`],
