            <input
              type="radio"
              name="reminder-target"
              value={option.value}
              checked={scope === option.value}
              disabled={busy}
              onChange={() => {
                setScope(option.value)
                request.current = crypto.randomUUID()
              }}
            />
            {option.label}
          </label>
        ))}
      </fieldset>
      <div>
        <p className="text-sm font-semibold">ข้อความทวงยอด</p>
        <LiveTemplateEditor
