const { test } = require('node:test'),
  assert = require('node:assert/strict'),
  fs = require('node:fs'),
  vm = require('node:vm'),
  ts = require('typescript')
const jsx = require('react/jsx-runtime')
function load(file, deps) {
  const context = {
    exports: {},
    require: (name) => {
      if (name in deps) return deps[name]
      throw Error('Unexpected dependency ' + name)
    },
  }
  vm.runInNewContext(
    ts.transpileModule(fs.readFileSync(file, 'utf8'), {
      compilerOptions: { module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX },
    }).outputText,
    context,
  )
  return context.exports
}
function nodes(value) {
  if (Array.isArray(value)) return value.flatMap(nodes)
  if (!value || typeof value !== 'object') return []
  return [value, ...nodes(value.props?.children)]
}
test('Thai menu buttons switch the current four panels without invoking network or mutations', () => {
  const flags = Object.fromEntries(
    [
      'agent_control_center_enabled',
      'agent_orchestrator_enabled',
      'agent_knowledge_base_enabled',
      'agent_playground_enabled',
      'agent_analytics_enabled',
      'agent_advanced_guardrails_enabled',
    ].map((key) => [key, false]),
  )
  const data = {
    shopInstructions: '',
    config: { flags, monthlyLimit: 0, rateLimit: 10 },
    canManage: false,
    versions: [],
    sources: [],
    customers: [],
    jobs: [],
    audit: [],
    usage: [],
    used: 0,
    stats: null,
  }
  const state = [],
    react = {
      useState(initial) {
        const i = react.index++
        if (!(i in state)) state[i] = i === 1 ? data : initial
        return [state[i], (next) => (state[i] = next)]
      },
      useEffect() {},
      useCallback: (fn) => fn,
      useRef: () => ({ current: null }),
    }
  const shared = { react: react, 'react/jsx-runtime': jsx, 'next/link': 'a' }
  const guide = load('components/chatbot/AgentUserGuide.tsx', shared)
  const { AgentControlCenter } = load('components/chatbot/AgentControlCenter.tsx', {
    ...shared,
    '@/components/ui/page-banner': { PageBanner: 'header' },
    '@/components/chatbot/AgentOverview': { AgentOverview: 'overview' },
    '@/components/chatbot/AgentHandoverQueue': { AgentHandoverQueue: 'handover' },
