const assert = require('node:assert/strict')
const { test } = require('node:test')
const fs = require('node:fs')
const path = require('node:path')
const vm = require('node:vm')
const ts = require('typescript')

function loadAi(response, visionError = false, products = []) {
  const requests = []
  let failed = 0
  class GoogleGenAI {
    constructor() {
      this.models = {
        generateContent: async (request) => {
          requests.push(request)
          if (response instanceof Error) throw response
          return response
        },
      }
    }
  }
  class ApiError extends Error {}
  class AiAgentError extends Error {
    constructor(code, message, status = 503) {
      super(message)
      this.code = code
      this.status = status
    }
  }
  const modules = {
    '@/lib/features/agents/llm-vision': {
      loadLlmImages: async () => {
        if (visionError) throw Error('IMAGE_DOWNLOAD_FAILED')
        return [{ mimeType: 'image/png', data: 'aW1hZ2U=' }]
      },
    },
    'server-only': {},
    '@google/genai': { ApiError, GoogleGenAI },
    '@/lib/feature-access': { hasFeature: async () => true },
    '@/lib/features/agents/ai-errors': { AiAgentError },
    '@/lib/features/inbox/inbox-automation-window': { assertAutomationWindow: async () => {} },
    '@/lib/features/agents/agent-control-ai': {
      prepareAgentGeneration: async (_db, ctx) => ({
        tenantId: ctx.tenantId,
        usageId: 'usage-1',
        products,
        systemInstruction: 'Select only grounded reply facts.',
      }),
      finishAgentGeneration: async (_db, _control, text) => text,
      failAgentGeneration: async () => {
        failed++
      },
      sanitizeAgentHistory: (text) => text,
    },
  }
  const exports = {}
  const code = ts.transpileModule(
    fs.readFileSync(path.join(__dirname, '..', 'lib/features/agents/ai-agent.ts'), 'utf8'),
    {
      compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
    },
  ).outputText
  vm.runInNewContext(code, {
    exports,
    URL,
    process: { env: { GEMINI_API_KEY: 'test-key' } },
    console: { log() {}, warn() {}, error() {} },
    setTimeout,
    require: (name) => {
      assert.ok(Object.hasOwn(modules, name), `Unexpected dependency: ${name}`)
      return modules[name]
    },
  })
  const db = {
    from(table) {
      assert.notEqual(
        table,
        'products',
        'Catalog must be loaded once by the managed context builder',
      )
      const query = {
        select() {
          return query
        },
        eq() {
          return query
        },
        order() {
          return query
        },
        async limit() {
          return {
            data:
              table === 'messages'
                ? [{ sender: 'customer', body: 'ขอทราบรายละเอียด', attachments: [] }]
                : [],
            error: null,
          }
        },
      }
      return query
    },
  }
  return { agent: exports, db, requests, failed: () => failed }
}

const context = {
