test('headless timer resolves an expired round once and cancels its background work on unmount', async () => {
  let effect,
    tick,
    cleanup,
    clock = 0,
    notifications = 0,
    cleared = false
  const calls = []
  const listeners = new Map()
  const { LiveAuctionTimer } = load(
    'components/live-cf/LiveAuctionTimer.tsx',
    {
      react: {
        useRef: (current) => ({ current }),
        useEffect: (callback) => {
          effect = callback
        },
      },
    },
    {
      AbortController,
      URLSearchParams,
      performance: { now: () => clock },
      document: {
        visibilityState: 'visible',
        addEventListener: (name, fn) => listeners.set(name, fn),
        removeEventListener: (name) => listeners.delete(name),
      },
      setInterval: (callback) => {
        tick = callback
        return 1
      },
      clearInterval: () => {
        cleared = true
      },
      fetch: async (_url, init) => {
        calls.push(init)
        return {
          ok: true,
          status: 200,
          json: async () => ({
            status: init.method === 'POST' ? 'closed' : 'active',
            serverNow: '2026-01-01T00:00:00Z',
            ends_at: '2026-01-01T00:00:01Z',
          }),
        }
      },
    },
  )
  assert.equal(
    LiveAuctionTimer({
      tenantId: 'tenant',
      auctionId: 'auction',
      onResolved: () => notifications++,
    }),
    null,
  )
  cleanup = effect()
  await new Promise(setImmediate)
  clock = 1000
  tick()
  await new Promise(setImmediate)
  assert.equal(JSON.parse(calls[1].body).action, 'expire')
  assert.equal(notifications, 1)
  tick()
  assert.equal(calls.length, 2)
  cleanup()
  assert.equal(cleared, true)
  assert.equal(calls[0].signal.aborted, true)
  assert.equal(listeners.size, 0)
})

