})

test('auction setup persists typed replies, rejects unsafe public variables and mismatched Pages', async () => {
  const inserted = []
  let linksReady = true
  let selectedBank = { id: orderId }
  let hostError = null
  const db = {
    from(table) {
      const q = {
        select: () => q,
        eq: () => q,
        insert(value) {
          inserted.push(value)
          return q
