        },
      }
      return q
    },
  }
  const api = load(
    'app/api/live-cf/auction/route.ts',
    {
      'next/server': {},
      '@/lib/auth': { getActor: async () => ({ kind: 'user', id: 'signed-in-owner' }) },
      '@/lib/features/commerce/auction-hosts': {
        auctionHostIds: async (_db, actorId, pageId) => {
