  let sends = 0,
    reservations = 0,
    busy = false,
    balance = 10
  const deliveries = new Map()
  const recipients = []
  const db = {
    from(table) {
      const q = {
        select() {
          return this
        },
        eq() {
          return this
        },
        order() {
          return this
        },
        range: async () => ({
          data: [...deliveries].map(([customer_id, value]) => ({ customer_id, ...value })),
          error: null,
        }),
        maybeSingle: async () => ({
          data:
