const assert = require('node:assert/strict')
const { readFileSync } = require('node:fs')
const { test } = require('node:test')
const vm = require('node:vm')
const ts = require('typescript')

function load(file, deps, globals = {}) {
  const context = {
    exports: {},
    console: { error() {}, warn() {} },
    process: { env: {} },
    require: (name) => {
      if (name in deps) return deps[name]
      if (name === '@/lib/full-access') return { temporaryFullAccess: false }
      if (name === '@/lib/features/overview/overview-diagnostics') return { logOverviewError() {} }
      throw Error('Unexpected dependency ' + name)
    },
    ...globals,
  }
  vm.runInNewContext(
    ts.transpileModule(readFileSync(file, 'utf8'), {
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2022,
        jsx: ts.JsxEmit.ReactJSX,
      },
    }).outputText,
    context,
  )
  return context.exports
}
const id = '11111111-1111-4111-8111-111111111111'
class InboxError extends Error {
  constructor(message, status = 400, code = 'INBOX_ERROR') {
    super(message)
    this.status = status
    this.code = code
  }
}

function tenants(results, picked = id) {
  const selections = []
