    from(table) {
      const query = {
        select(columns) {
          calls.push([table, 'select', columns])
          return this
        },
        eq(key, value) {
          calls.push([table, key, value])
          return this
        },
        in(key, values) {
          calls.push([table, key, Array.from(values)])
          return this
        },
        order() {
          return this
        },
        returns: async () => ({ data: [{ id }], error: null }),
        then(resolve, reject) {
          return Promise.resolve({ data: [{ tenant_id: id }], error: null }).then(resolve, reject)
        },
      }
      return query
    },
  }
