function callback(options = {}) {
  const exchanges = [],
    logs = [],
    rpcCalls = [],
    pageCalls = [],
    subscriptionCalls = [],
    cookieWrites = []
  const mod = load(
    'app/auth/callback/route.ts',
    {
      'next/server': {
        NextResponse: {
          redirect: (url) => ({
            location: String(url),
            cookies: { set: (...args) => cookieWrites.push(args) },
          }),
        },
      },
      '@/lib/oauth': oauth,
      '@/lib/supabase/server': {
        supabaseServer: async () => ({
          auth: {
            exchangeCodeForSession: async (...args) => {
              exchanges.push(args)
              if (options.throwExchange) throw Error('private-exception-detail')
              return (
                options.exchange ?? {
                  data: {
                    session: { provider_token: 'private-provider-token', user: { id: 'user-id' } },
                  },
                  error: null,
                }
              )
            },
          },
        }),
        supabaseAdmin: () => ({
          rpc: async (...args) => {
            rpcCalls.push(args)
            return { data: 1, error: options.rpcError ?? null }
          },
        }),
      },
      '@/lib/integrations/facebook/oauth': {
        subscribePage: async (...args) => {
          subscriptionCalls.push(args)
          return options.subscribeError ?? null
        },
        verifiedAdminPages: async (pages) => pages,
        listPages: async (token) => {
          pageCalls.push(token)
          if (options.pageError) throw Error('private-graph-detail')
          return (
            options.pages ?? [{ id: 'page-id', name: 'Shop', accessToken: 'private-page-token' }]
          )
        },
      },
    },
    { console: { error: (...args) => logs.push(args) } },
  )
  const run = async (path, cookie) => {
    const url = new URL(path, 'http://localhost:3000')
    return mod.GET({
      url: url.toString(),
      nextUrl: url,
      cookies: { get: () => (cookie === undefined ? undefined : { value: cookie }) },
    })
  }
  return { run, exchanges, logs, rpcCalls, pageCalls, cookieWrites, subscriptionCalls }
}

