  )
  await asRole('service_role', null, async () => {
    assert.equal((await sync(otherId, [page()])).rows[0].saved, 1)
    assert.equal((await sync(otherId, [page()])).rows[0].saved, 1)
  })
  assert.equal(
    (
      await db.query(
        'select role from public.tenant_members where tenant_id = $1 and user_id = $2',
        [original.id, otherId],
      )
    ).rows[0].role,
    'owner',
