    const tables = (
      await db.query(
        "select relname,relrowsecurity from pg_class where relnamespace='public'::regnamespace and relkind='r'",
      )
    ).rows
    assert.ok(tables.length > 70)
    assert.deepEqual(
      tables.filter((t) => !t.relrowsecurity),
      [],
