// Isolated PostgreSQL and real validation; never reads .env or contacts Supabase.
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const ts = require('typescript')
const { PGlite } = require(process.argv[2] || '@electric-sql/pglite')
const catalog = {}
new Function(
  'exports',
  ts.transpileModule(
    fs.readFileSync(path.join(__dirname, '../lib/features/vision/image-rules.ts'), 'utf8'),
    { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } },
  ).outputText,
)(catalog)
const draft = {
  name: 'Test',
  trigger_type: 'slip',
  response_text: 'Received',
  media_url: null,
  is_active: true,
}
assert.equal(catalog.imageRuleError(draft), null)
assert.equal(
  catalog.imageRuleError({
    ...draft,
    response_text: '',
    media_url: 'https://example.com/image.png',
  }),
  null,
)
for (const changes of [
  { name: ' ' },
  { trigger_type: 'invalid' },
  { response_text: '', media_url: null },
  { response_text: 'x'.repeat(2001) },
  { media_url: 'javascript:alert(1)' },
])
  assert.ok(catalog.imageRuleError({ ...draft, ...changes }))
async function main() {
