    },
    '@/lib/features/inbox/inbox-server': {
      inboxTenant: async () => {
        if (denied) throw new Error('Forbidden')
        return { db, actor: { id: 'actor' }, tenantId: 'tenant' }
      },
      inboxError: () => ({ status: 503 }),
    },
  })
  return {
    api,
    queries,
    request: { nextUrl: { searchParams: new URLSearchParams({ tenantId: 'tenant' }) } },
  }
}

