test('Inbox filters message inserts to the active customer and replaces its channel on room changes', async () => {
  const values = [],
    memos = [],
    effects = [],
    pending = [],
    channels = [],
    removed = [],
    timers = new Set()
  let cursor = 0,
    tree,
    timerId = 0
  const same = (a, b) => a && b && a.length === b.length && a.every((v, i) => Object.is(v, b[i]))
  const react = {
    useState(initial) {
      const i = cursor++
      if (!(i in values)) values[i] = initial
      return [values[i], (v) => (values[i] = typeof v === 'function' ? v(values[i]) : v)]
    },
    useRef(initial) {
      const i = cursor++
      if (!(i in values)) values[i] = { current: initial }
      return values[i]
    },
    useMemo(fn, deps) {
      const i = cursor++
      if (!memos[i] || !same(memos[i].deps, deps)) memos[i] = { value: fn(), deps }
      return memos[i].value
    },
    useCallback(fn, deps) {
      return react.useMemo(() => fn, deps)
    },
    useEffect(fn, deps) {
      const i = cursor++
      if (!effects[i] || !same(effects[i].deps, deps))
        pending.push(() => {
          effects[i]?.cleanup?.()
          effects[i] = { deps, cleanup: fn() }
        })
    },
  }
  const db = {
    from() {
      const q = {
        select() {
          return q
        },
        eq() {
          return q
        },
        order() {
          return q
        },
        limit() {
          return q
        },
        abortSignal() {
          return q
        },
        async maybeSingle() {
          return { data: null, error: null }
        },
        then(resolve, reject) {
          return Promise.resolve({ data: [], error: null }).then(resolve, reject)
        },
      }
      return q
    },
    channel(name) {
      const c = {
        name,
        listeners: [],
        on(_, filter, callback) {
          c.listeners.push({ filter, callback })
          return c
        },
        subscribe(callback) {
          c.status = callback
          return c
        },
      }
      channels.push(c)
      return c
    },
    async removeChannel(c) {
      removed.push(c)
      c.status('CLOSED')
    },
  }
  const timer = () => {
      timers.add(++timerId)
      return timerId
    },
    clear = (id) => timers.delete(id),
    api = {}
  const request = load('lib/features/inbox/inbox-request.ts', {}, { AbortController }),
    realtime = load('lib/features/inbox/inbox-realtime.ts')
  const documentState = {
    visibilityState: 'visible',
    addEventListener() {},
    removeEventListener() {},
  }
  const visibility = load('lib/realtime-visibility.ts', {}, { document: documentState })
  vm.runInNewContext(
    ts.transpileModule(fs.readFileSync('components/inbox/InboxClient.tsx', 'utf8'), {
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2022,
        jsx: ts.JsxEmit.ReactJSX,
      },
    }).outputText,
    {
      exports: api,
      AbortController,
      fetch: async (url) => ({
        ok: true,
        json: async () => ({
          chats: props.initialChats.filter(
            (chat) =>
              chat.customer.tenant_id ===
              new URL(url, 'https://offline.test').searchParams.get('tenantId'),
          ),
          comments: [],
          hasMore: false,
        }),
      }),
      console: { log() {}, info() {}, warn() {}, error() {} },
      process: { env: { NODE_ENV: 'test' } },
      setTimeout: timer,
      clearTimeout: clear,
      setInterval: timer,
      clearInterval: clear,
      window: { addEventListener() {}, removeEventListener() {} },
      document: documentState,
      require: (name) => {
        if (name === 'react') return react
        if (name === 'react/jsx-runtime')
          return {
            jsx: (type, props) => ({ type, props }),
            jsxs: (type, props) => ({ type, props }),
          }
        if (name === '@/lib/supabase/browser') return { supabaseBrowser: () => db }
        if (name === '@/lib/types') return { isMissingCustomerAvatarColumn: () => false }
        if (name === '@/lib/features/inbox/inbox-request') return request
        if (name === '@/lib/features/inbox/inbox-realtime') return realtime
        if (name === '@/lib/realtime-visibility') return visibility
        if (name === '@/hooks/inbox/useInboxState')
          return { useInboxState: () => ({ data: null, error: null, refresh: async () => {} }) }
        if (name === '@/lib/utils') return { cn: () => '' }
        return new Proxy({}, { get: (_, key) => key })
      },
    },
  )
  const chats = ['a', 'b'].map((id) => ({
    customer: { id, tenant_id: 'tenant', last_message_at: null },
    preview: null,
    latestSlip: null,
  }))
  const props = {
    initialChats: chats,
    initialComments: [],
    initialSelectedId: 'a',
