    .find((n) => n.type === 'ChatList')
    .props.onOpen('b')
  render()
  await flush()
  assert.equal(channels.length, 2)
  assert.equal(removed.length, 1)
  const message = {
    id: 'message',
    customer_id: 'b',
    sender: 'customer',
    body: 'hello',
    created_at: '2026-10-20T00:00:00Z',
    attachments: [],
  }
