const assert = require('node:assert/strict'),
  fs = require('node:fs'),
  vm = require('node:vm'),
  ts = require('typescript')
const { test } = require('node:test')
function load(file, deps) {
  const context = { exports: {}, console, process: { env: {} }, require: (n) => deps[n] }
  vm.runInNewContext(
    ts.transpileModule(fs.readFileSync(file, 'utf8'), {
      compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
    }).outputText,
    context,
  )
  return context.exports
}
function fixture(remaining) {
  let balance = remaining,
    sent = 0
  const claims = new Set()
  const quota = load('lib/message-quota.ts', {
    'server-only': {},
    '@/lib/features/inbox/inbox-automation-window': { assertAutomationWindow: async () => {} },
    '@/lib/features/billing/billing': {
      reserveCredits: async () => {
        if (balance <= 0) return { monthly: 0, topup: 0 }
        balance--
        return { monthly: 1, topup: 0 }
      },
      settleCredits: async (_db, _tenant, r, used) => {
        balance += r.monthly + r.topup - used
      },
    },
  })
  const db = {
    rpc: async (name) => ({ data: name === 'start_inbox_delivery' ? 'lease' : null, error: null }),
    from: () => {
      let external
      return {
        insert(v) {
          external = v.external_id
          return this
        },
        select() {
          return this
        },
        eq() {
          return this
        },
        update() {
          return this
        },
        single: async () => {
          if (claims.has(external)) return { error: { code: '23505' } }
          claims.add(external)
          return { data: { id: 'message' } }
        },
        maybeSingle: async () => ({ data: { tenant_id: 'shop' } }),
      }
    },
  }
  const notify = load('lib/features/slips/notify.ts', {
    ...require('./helpers/slip-confirmation-dependencies.cjs'),
    'server-only': {},
    '@/lib/features/inbox/inbox-automation-window': { assertAutomationWindow: async () => {} },
    '@/lib/message-quota': quota,
    '@/lib/integrations/facebook/client': {
      SendApiError: class extends Error {},
      sendMessage: async () => {
        sent++
      },
      sendText: async () => {
        sent++
      },
      sendPaymentCard: async () => {
        sent++
      },
      isWindowOrTagError: () => false,
    },
  })
  return {
    quota,
    notify,
    db,
    customer: { id: 'customer', psid: '123', token: 'test' },
    balance: () => balance,
    sent: () => sent,
  }
}
test('Auto-reply cannot send message 101 and duplicate delivery never consumes extra credits', async () => {
  const f = fixture(100)
  for (let i = 0; i < 100; i++)
    assert.equal(await f.notify.deliverOnce(f.db, f.customer, 'reply:' + i, 'hello'), true)
  assert.equal(await f.notify.deliverOnce(f.db, f.customer, 'reply:0', 'hello'), false)
  await assert.rejects(
    f.notify.deliverOnce(f.db, f.customer, 'reply:101', 'hello'),
    (error) => error.code === 'MESSAGE_QUOTA_EXHAUSTED',
  )
  assert.equal(f.sent(), 100)
  assert.equal(f.balance(), 0)
})
test('failed delivery refunds one reserved message and a retry uses the same shared balance', async () => {
  const f = fixture(1)
  await assert.rejects(
    f.quota.sendWithMessageCredit(f.db, 'shop', async () => {
      throw Error('Meta unavailable')
    }),
    /Meta unavailable/,
  )
  assert.equal(f.balance(), 1)
  await f.notify.deliverOnce(f.db, f.customer, 'next', 'hello')
  assert.equal(f.balance(), 0)
})
test('rich replies charge per physical message; batch-reserved broadcasts are not charged twice', async () => {
  const f = fixture(2)
  await assert.rejects(
    f.notify.deliverRichOnce(f.db, f.customer, 'rich', 'three parts', [
      { text: 'a' },
      { text: 'b' },
      { text: 'c' },
    ]),
    /เครดิตข้อความหมด/,
  )
  assert.equal(f.sent(), 2)
  assert.equal(f.balance(), 0)
  const broadcast = fixture(99)
  await broadcast.notify.deliverRichOnce(
    broadcast.db,
    broadcast.customer,
    'bc:campaign:customer',
    'hello',
    [{ text: 'hello' }],
  )
  assert.equal(broadcast.balance(), 99)
  assert.equal(broadcast.sent(), 1)
})
test('human handoff blocks bot sends before message insertion or quota consumption', async () => {
  const f = fixture(100)
  f.db.rpc = async () => ({ error: { code: '40001' } })
  await assert.rejects(
    f.notify.deliverOnce(f.db, f.customer, 'reply:paused', 'hello'),
    (e) => e.code === 'BOT_DELIVERY_BLOCKED',
  )
  assert.equal(f.sent(), 0)
  assert.equal(f.balance(), 100)
})

const assert = require('node:assert/strict')
const { readFileSync } = require('node:fs')
const { join } = require('node:path')
const { PGlite } = require(process.argv[2] || '@electric-sql/pglite')
async function main() {
  const db = new PGlite()
  try {
    await db.exec(`create table bot_settings(tenant_id text primary key, followup_steps jsonb, updated_at timestamptz);
      create table follow_up_jobs(id integer primary key, step integer, text text, status text);
      create function gate_test() returns trigger language plpgsql as $$begin raise exception 'gate should be bypassed'; end$$;
      create trigger bot_settings_ai_plan_gate before update on bot_settings for each row execute function gate_test();
      create trigger bot_settings_followup_plan_gate before update on bot_settings for each row execute function gate_test();
      alter table bot_settings disable trigger bot_settings_followup_plan_gate;`)
    const steps = [
      { delay_minutes: 15, text: 'Hello {name}, pay {total}', custom: 'keep' },
      { delay_minutes: 60, text: 'คุณ {name} กรุณาชำระ {total}' },
      { delay_minutes: 120, text: 'Custom {name} {total}' },
    ]
    await db.query('insert into bot_settings values ($1,$2,null)', [
      'tenant',
      JSON.stringify(steps),
    ])
    await db.query('insert into follow_up_jobs values (1,1,$1,$2),(2,1,$1,$3)', [
      'Hello {name} {total}',
      'scheduled',
      'sent',
    ])
    const sql = readFileSync(join(__dirname, '../supabase/migrate-followup-variables.sql'), 'utf8')
    await db.exec(sql)
    const first = (await db.query('select * from bot_settings')).rows[0]
    assert.equal(
      first.followup_steps[0].text,
      'คุณ {ชื่อลูกค้า} ยังไม่ได้ส่งสลิปสำหรับยอด {ยอดเงิน} บาทนะคะ โอนแล้วส่งสลิปในแชทนี้ได้เลยค่ะ',
    )
    assert.equal(first.followup_steps[0].custom, 'keep')
    assert.equal(first.followup_steps[1].text, 'คุณ {ชื่อลูกค้า} กรุณาชำระ {ยอดเงิน}')
    assert.equal(first.followup_steps[2].text, 'Custom {ชื่อลูกค้า} {ยอดเงิน}')
    assert.equal(first.followup_steps[2].delay_minutes, 120)
    const jobs = (await db.query('select * from follow_up_jobs order by id')).rows
    assert.equal(jobs[0].text, first.followup_steps[0].text)
    assert.equal(jobs[1].text, 'Hello {name} {total}')
    await db.exec(sql)
    assert.deepEqual((await db.query('select * from bot_settings')).rows[0], first)
    const gates = (
      await db.query(
        'select tgname,tgenabled from pg_trigger where not tgisinternal order by tgname',
      )
    ).rows
    assert.deepEqual(
      gates.map((g) => g.tgenabled),
      ['O', 'D'],
    )
    console.log(
      'Migration passed: Thai/English mapping, custom messages and fields, pending jobs, preserved history, trigger state, rerun.',
    )
  } finally {
    await db.close()
  }
}
main().catch((error) => {
  console.error(error)
  process.exitCode = 1
})

