function fixture({
  enabled = true,
  existing = false,
  claimExisting = false,
  start = true,
  verdict = 'valid',
  providerFault = false,
  saveFailure = false,
  production = false,
  send = false,
  foreignCustomer = false,
  timestampOffset = 0,
} = {}) {
  let providerCalls = 0,
    claims = 0,
    starts = 0,
    completed = 0,
    recovered = 0
  const records = [],
    filters = []
  const orderCreatedAt = Date.now()
  const db = {
    from(table) {
      const q = {
        select() {
          return q
        },
        eq(key, value) {
          filters.push([table, key, value])
          return q
        },
        in() {
          return q
        },
        update() {
          return q
        },
        maybeSingle: async () => ({
          data:
            table === 'payment_pro_attempts' && existing
              ? { id, slip_id: 'slip', customer_id: foreignCustomer ? 'someone-else' : 'customer' }
              : null,
        }),
        single: async () => ({
          data: {
            id: 'slip',
            status: verdict === 'valid' ? 'valid' : 'error',
            amount: 100,
            trans_ref: 'ref',
            note: null,
          },
        }),
        then(resolve, reject) {
          return Promise.resolve({
            data:
              table === 'bank_accounts'
                ? [{ bank_code: 'KTB', account_number: '9260337828', is_active: true }]
                : table === 'orders'
                  ? [{ id: 'order', created_at: new Date(orderCreatedAt).toISOString() }]
                  : null,
          }).then(resolve, reject)
        },
      }
      return q
    },
    rpc: async (name, args) => {
      records.push([name, args])
      if (name === 'claim_payment_pro') {
        claims++
        return {
          data: {
            id,
            slip_id: 'slip',
            customer_id: 'customer',
            claim_token: claimExisting || claims > 1 ? null : 'claim',
            expected_satang: 10000,
            image_path: null,
            order_ids: ['order'],
          },
        }
      }
      if (name === 'start_payment_pro_provider') {
        starts++
        return { data: start }
      }
      if (name === 'complete_payment_pro') {
        completed++
        return saveFailure ? { error: { code: 'DB_DOWN' } } : { data: null }
      }
      if (name === 'review_payment_pro_failure') {
        recovered++
        return { data: null }
      }
      throw Error(name)
    },
  }
  const config = { riskEngine: enabled, messengerAutomation: true }
  const api = load(
    'lib/features/payments/payment-pro.ts',
    {
      'server-only': {},
      'node:crypto': require('node:crypto'),
      '@/lib/features/payments/payment-pro-flags': {
        paymentProConfig: async () => config,
        paymentProAvailable: () => true,
      },
      '@/lib/features/payments/payment-pro-core': core,
      '@/lib/features/slips/slip-timestamp': require('./helpers/load-typescript.cjs')(
        'lib/features/slips/slip-timestamp.ts',
        { 'server-only': {}, '@/lib/features/payments/payment-pro-core': core },
      ),
      '@/lib/features/slips/slipok': {
        verifyWithSlipOK: async (input) => {
          providerCalls++
          assert.equal(input.expectedAmount, 100)
          assert.equal('log' in input, false)
          return {
            verdict,
            providerFault,
            amount: 100,
            transRef: 'ref',
            receiverBank: '006',
            receiverAccount: '9260337828',
            raw: {
              data: { transTimestamp: new Date(orderCreatedAt + timestampOffset).toISOString() },
            },
          }
        },
      },
      '@/lib/features/slips/receiver-matching': { receiverMatchesAny: () => true },
      '@/lib/features/vision/vision-image': { validateVisionFile: async () => true },
    },
    {
      process: {
        env: {
          NODE_ENV: production ? 'production' : 'development',
          PAYMENT_PRO_SEND_ENABLED: send ? 'true' : 'false',
        },
      },
    },
  )
  return {
    api,
    db,
    records,
    filters,
    run: () =>
      api.processPaymentPro(db, {
        qr: 'test-qr',
        tenant: { id: tenant, account_number: '9260337828', bank_code: 'KTB' },
        customerId: 'customer',
        expectedAmount: 0.01,
      }),
    counts: () => ({ providerCalls, claims, starts, completed, recovered }),
  }
}
test('Pro applies the same 60-second timestamp boundary before finalizing payment', async () => {
  for (const timestampOffset of [0, -60000]) {
    const f = fixture({ timestampOffset })
    await f.run()
    assert.equal(f.counts().completed, 1)
    assert.equal(f.counts().recovered, 0)
  }
  for (const timestampOffset of [-60001, -90000]) {
    const f = fixture({ timestampOffset })
    await assert.rejects(
      f.run(),
      (error) =>
        error.code === 'SLIP_TIMESTAMP_REJECTED' &&
        error.message === 'สลิปนี้ทำรายการก่อนสร้างออเดอร์ ไม่สามารถใช้ชำระเงินได้',
    )
    assert.equal(f.counts().providerCalls, 1)
    assert.equal(f.counts().completed, 0)
    assert.equal(f.counts().recovered, 1)
  }
})

