      plan: 'free',
      broadcast_credits: 100,
      broadcast_topup_credits: 80,
      slip_used: 0,
    })
    await db.query('delete from tenants where id=$1', [tenant])
    assert.equal(
      (await db.query('select count(*)::integer as n from payment_receipts')).rows[0].n,
      2,
    )
    await db.exec("delete from slips where trans_ref='sale-ref'")
    await assert.rejects(
      db.exec("insert into slips(trans_ref,status) values ('sale-ref','valid')"),
      /accepted/,
    )
    console.log(
      'Payment SQL checks passed: rerun, proof, duplicates, retry, credit arithmetic, renewal, expiry, permissions, retained ledger.',
    )
  } finally {
    await db.close()
  }
}
main().catch((error) => {
  console.error(error)
