// No .env or real network/database access. Exercise real handlers with isolated dependencies.
const assert = require('node:assert/strict')
const { test } = require('node:test')
const { readFileSync } = require('node:fs')
const { join } = require('node:path')
const vm = require('node:vm')
const ts = require('typescript')
const tenant = '11111111-1111-4111-8111-111111111111'
const id = '22222222-2222-4222-8222-222222222222'
const owner = { kind: 'user', id, isPlatformAdmin: false }
const admin = { ...owner, isPlatformAdmin: true }
function load(file, dependencies = {}, extra = {}) {
  const exports = {}
  const code = ts.transpileModule(readFileSync(join(__dirname, '..', file), 'utf8'), {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
  }).outputText
  vm.runInNewContext(
    code,
    {
      exports,
      Buffer,
      require: (name) => {
        if (name === 'server-only') return {}
        if (name in dependencies) return dependencies[name]
        if (name === '@/lib/full-access') return { temporaryFullAccess: false }
        throw Error(`Unexpected dependency: ${name}`)
      },
      console,
      File,
      FormData,
      Request,
      Response,
      AbortSignal,
      Date,
      ...extra,
    },
    { filename: file },
  )
  return exports
}
const plans = load('lib/features/billing/plans.ts')
const validation = load('lib/features/payments/payment-validation.ts', {
  '@/lib/features/banking/banks': { BANKS: [], findBank: () => null },
  '@/lib/image-signature': load('lib/image-signature.ts'),
})
function fixture(actor = admin, options = {}) {
  const calls = [],
    stored = [],
    removed = []
  const db = {
    from: (table) => {
      calls.push(['from', table])
      const query = {}
      for (const method of ['select', 'eq', 'is', 'update'])
        query[method] = (...args) => {
          calls.push([method, ...args])
          return query
        }
      query.maybeSingle = async () => ({
        data:
          options.request === null
            ? null
            : options.saved === false && calls.some((c) => c[0] === 'update')
              ? null
              : {
                  id,
                  tenant_id: tenant,
                  status: 'pending',
                  proof_path: options.proof ?? null,
                  ...options.request,
                },
        error: null,
      })
      return query
    },
    rpc: async (name, args) => {
      calls.push(['rpc', name, args])
      return { data: null, error: options.rpcError ?? null }
    },
    storage: {
      from: (bucket) => ({
        upload: async (path, file) => {
          stored.push({ bucket, path, file })
          return { error: null }
        },
        remove: async (paths) => {
          removed.push(...paths)
          return { error: null }
        },
        createSignedUrl: async (path, ttl) => {
          calls.push(['signed', path, ttl])
          return { data: { signedUrl: 'https://storage.example/private?expires=120' }, error: null }
        },
      }),
    },
  }
  const deps = {
    'next/server': { NextResponse: { json: (value, init) => Response.json(value, init) } },
    '@/lib/auth': {
      getActor: async () => actor,
      isPlatformAdmin: (a) => a.kind === 'internal' || a.isPlatformAdmin,
      canAccessTenant: async () => options.access !== false,
    },
    '@/lib/supabase/server': { supabaseAdmin: () => db },
    '@/lib/utils': { UUID: /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i },
    '@/lib/features/payments/payment-validation': validation,
    '@/lib/features/billing/billing': {
      getBilling: async () => ({ plan: 'starter', monthly: 1500, topup: 0, slipRemaining: 500 }),
    },
    '@/lib/features/billing/billing-verification': {
      APPROVAL_SUCCESS: 'อนุมัติสำเร็จ! ระบบเพิ่มเครดิตให้เรียบร้อยแล้ว',
      BILLING_VERIFICATION_COLUMNS: 'tenant_id,status,proof_path',
      verifyBillingRequest: async () => ({ ok: true, status: 'pending', message: 'รอตรวจสอบ' }),
    },
    'node:crypto': { randomUUID: () => id, createHash: require('node:crypto').createHash },
  }
  return { db, deps, calls, stored, removed }
}
const params = { params: Promise.resolve({ id: tenant }) }
const json = (body) =>
  new Request('https://local.test/api', {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  })

test('owner dashboard redirects non-admins and rejects internal tokens as dashboard identities', async () => {
  for (const actor of [null, owner, { kind: 'internal' }]) {
    const { deps, calls } = fixture(actor)
    const mod = load('lib/admin.ts', {
      ...deps,
      'next/navigation': {
        redirect: (path) => {
