function billingVerificationFixture(options = {}) {
  const state = {
    receipt: options.receipt ?? null,
    activationCalls: 0,
    providerCalls: 0,
    updates: [],
  }
  const now = new Date()
  const thai = new Date(now.getTime() + 7 * 3600000).toISOString()
  const reference = 'verified-billing-ref'
  const amount = options.amount ?? 100
  const valid = {
    verdict: 'valid',
    receiverVerifiedByProvider: true,
    amount,
    transRef: reference,
    raw: {
      success: true,
      data: {
        success: true,
        amount,
        transRef: reference,
        receivingBank: '004',
        receiver: { account: { value: 'xxxxxx7890' } },
        transDate: thai.slice(0, 10).replaceAll('-', ''),
        transTime: thai.slice(11, 19),
      },
    },
  }
  const db = {
    from: (table) => {
      const q = {}
      for (const method of ['select', 'eq']) q[method] = () => q
      q.update = (values) => {
        state.updates.push(values)
        return q
      }
      q.then = (resolve, reject) =>
        Promise.resolve({ data: null, error: null }).then(resolve, reject)
      q.maybeSingle = async () => ({
        data:
          table === 'billing_payment_receipts'
            ? state.receipt
            : table === 'payment_transfer_ledger'
              ? (options.transferClaim ?? null)
              : table === 'payment_image_ledger'
                ? (options.imageClaim ?? null)
                : null,
        error: null,
      })
      q.insert = async (values) => {
        if (options.saveFailure) return { error: { code: 'XX001' } }
        state.receipt = values
        return { error: null }
      }
      return q
    },
    rpc: async (name, args) => {
      assert.equal(name, 'activate_billing_payment')
      assert.equal(args.p_request, id)
      state.activationCalls++
      return options.activationFailure
        ? { data: false, error: { code: 'XX001' } }
        : { data: true, error: null }
    },
    storage: {
      from: () => ({
        download: async () => ({
          data: new Blob([new Uint8Array([0xff, 0xd8, 0xff])], { type: 'image/jpeg' }),
          error: null,
        }),
      }),
    },
  }
  const mod = load(
    'lib/features/billing/billing-verification.ts',
    {
      'node:crypto': require('node:crypto'),
      '@/lib/features/billing/billing': {
        getBilling: async () => ({
          plan: 'starter',
          monthly: 1500,
          topup: 400,
          slipRemaining: 500,
        }),
      },
      '@/lib/features/payments/payments': {
        paymentReceiver: () => ({
          promptpayId: '0812345678',
          bankAccountNo: '1234567890',
          bankCode: '004',
        }),
      },
      '@/lib/features/payments/payment-validation': validation,
      '@/lib/features/slips/slipok': {
        slipVerificationConfigured: () => true,
        verifyWithSlipOK: async (input) => {
          state.providerCalls++
          assert.equal(input.expectedAmount, undefined)
          return options.verdict ? { ...valid, ...options.verdict } : valid
        },
      },
    },
    { Buffer, process: { env: { SLIPOK_BRANCH_ID: 'test-branch', SLIPOK_API_KEY: 'test-key' } } },
  )
  const request = {
    tenant_id: tenant,
    status: 'pending',
    proof_path: 'private.jpg',
    price_baht: 100,
    created_at: new Date(now.getTime() - 60000).toISOString(),
    receiver_promptpay_id: null,
    receiver_account_no: null,
    receiver_bank_code: null,
  }
  return { state, run: () => mod.verifyBillingRequest(db, id, request) }
}

