test('underpayment, provider failure, wrong receiver and shared-ledger duplicate stay pending without credit activation', async () => {
  for (const options of [
    { amount: 99.99 },
    { verdict: { verdict: 'duplicate' } },
    { verdict: { verdict: 'wrong_receiver', branchReceiverMismatch: true } },
    { verdict: { verdict: 'error', providerFault: true } },
    { verdict: { verdict: 'valid', raw: { success: true, data: { success: false } } } },
