function metadataFixture() {
  const values = [],
    memos = [],
    effects = [],
    pending = [],
    timers = new Map(),
    listeners = new Map(),
    signals = []
  let cursor = 0,
    now = 100000,
    timerId = 0,
    fetches = 0,
    fail = false,
    block = false,
    release
  const same = (a, b) => a && b && a.length === b.length && a.every((v, i) => Object.is(v, b[i]))
  const react = {
    useState(value) {
      const i = cursor++
      if (!(i in values)) values[i] = value
      return [
        values[i],
        (next) => {
          values[i] = typeof next === 'function' ? next(values[i]) : next
        },
      ]
    },
    useRef(value) {
      const i = cursor++
      return (values[i] ??= { current: value })
    },
    useCallback(fn, deps) {
      const i = cursor++
      if (!memos[i] || !same(memos[i].deps, deps)) memos[i] = { fn, deps }
      return memos[i].fn
    },
    useEffect(fn, deps) {
      const i = cursor++
      if (!effects[i] || !same(effects[i].deps, deps))
        pending.push(() => {
          effects[i]?.cleanup?.()
          effects[i] = { deps, cleanup: fn() }
        })
    },
  }
  class FakeDate extends Date {
    static now() {
      return now
    }
  }
  const document = {
    visibilityState: 'visible',
    addEventListener: (k, v) => listeners.set('document:' + k, v),
    removeEventListener: (k) => listeners.delete('document:' + k),
  }
  const globals = {
    AbortController,
    Date: FakeDate,
    document,
    window: {
      addEventListener: (k, v) => listeners.set(k, v),
      removeEventListener: (k) => listeners.delete(k),
    },
    setTimeout: (fn, ms) => {
      timers.set(++timerId, { fn, at: now + ms })
      return timerId
    },
    clearTimeout: (id) => timers.delete(id),
    fetch: async (_url, opts) => {
      fetches++
      signals.push(opts.signal)
      if (block) {
        block = false
        await new Promise((resolve) => {
          release = resolve
        })
      }
      return { ok: !fail, json: async () => ({ conversations: [] }) }
    },
  }
  const background = load('lib/background-refresh.ts', {}, globals)
  const api = load(
    'hooks/inbox/useInboxState.ts',
    {
      react,
      '@/lib/background-refresh': background,
      '@/lib/utils': { apiError: async () => 'Unavailable' },
      '@/lib/features/inbox/inbox-request': load(
        'lib/features/inbox/inbox-request.ts',
        {},
        { AbortController },
      ),
    },
    globals,
  )
  return {
    render(tenant = 'tenant-a', ids = ['one']) {
      cursor = 0
      const state = api.useInboxState(tenant, ids)
      while (pending.length) pending.shift()()
      return state
    },
    async advance(ms) {
      const end = now + ms
      for (let i = 0; i < 100; i++) {
        const next = [...timers].filter(([, v]) => v.at <= end).sort((a, b) => a[1].at - b[1].at)[0]
        if (!next) break
        now = next[1].at
        timers.delete(next[0])
        next[1].fn()
        await flush()
      }
      now = end
    },
    document,
    timers,
    listeners,
    signals,
    count: () => fetches,
    fail: () => {
      fail = true
    },
    block: () => {
      block = true
    },
    release: () => release?.(),
    cleanup() {
      for (const effect of effects) effect?.cleanup?.()
    },
  }
}

