const { test } = require('node:test'),
  assert = require('node:assert/strict'),
  fs = require('node:fs'),
  vm = require('node:vm'),
  ts = require('typescript')
function load(file, deps = {}) {
  const exports = {}
  vm.runInNewContext(
    ts.transpileModule(fs.readFileSync(file, 'utf8'), {
      compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
    }).outputText,
    {
      exports,
      console,
      Date,
      Map,
      Set,
      crypto: require('node:crypto').webcrypto,
      process: { env: {} },
      require: (name) => {
        if (name in deps) return deps[name]
        throw Error('Unexpected dependency ' + name)
      },
    },
  )
  return exports
}
const core = load('lib/features/agents/agent-control-core.ts', {
  '@/lib/domain-state': load('lib/domain-state.ts'),
})
function fixture({
  rules = '- ค่าส่ง 50 บาท\n- ตัดรอบส่งเวลา 13:00 น.\n- ตอบอย่างสุภาพ',
  error = false,
  quota = true,
  saved = [],
  savedError = false,
  knowledge = [],
  catalog = [],
} = {}) {
  let savedRules = rules,
    savedRows = saved,
    reserves = 0
  const reads = [],
    writes = []
  class AiAgentError extends Error {
    constructor(code, message, status) {
      super(message)
      this.code = code
      this.status = status
    }
  }
  const api = load('lib/features/agents/agent-control-ai.ts', {
    'server-only': {},
    '@/lib/features/store-rules/store-rule-items': load(
      'lib/features/store-rules/store-rule-items.ts',
    ),
    '@/lib/features/agents/ai-errors': { AiAgentError },
    '@/lib/features/store-rules/shop-persona-settings': load(
      'lib/features/store-rules/shop-persona-settings.ts',
      {
        '@/lib/features/store-rules/store-rule-items': load(
          'lib/features/store-rules/store-rule-items.ts',
        ),
      },
    ),
    '@/lib/features/agents/agent-control-core': core,
    '@/lib/features/agents/agent-control-flags': {
      agentControlConfig: async () => ({
        flags: { agent_orchestrator_enabled: true, agent_knowledge_base_enabled: true },
        capabilities: { products: true },
      }),
    },
  })
  const db = {
    rpc: async (name, args) => {
      assert.equal(name, 'start_agent_ai_call')
      assert.ok(typeof args.p_tenant === 'string')
      reserves++
      return { data: quota ? { id: 'usage' } : { reason: 'AI_QUOTA_EXHAUSTED' } }
    },
    from(table) {
      const read = { table, filters: [] }
      reads.push(read)
      let update = false
      const q = {
        select() {
          return q
        },
        eq(k, v) {
          read.filters.push([k, v])
          return q
        },
        order() {
          return q
        },
        range(start, end) {
          read.range = [start, end]
          return q
        },
        limit() {
          return q
        },
        maybeSingle() {
          return q
        },
        update(value) {
          update = true
          writes.push(value)
          return q
        },
        then(resolve, reject) {
          return Promise.resolve({
            data: update
              ? { id: 'usage' }
              : table === 'products'
                ? catalog.slice(read.range?.[0] ?? 0, (read.range?.[1] ?? 99) + 1)
                : table === 'agent_knowledge_sources'
                  ? knowledge
                  : table === 'inbox_quick_replies'
                    ? savedRows.filter(
                        (row) =>
                          !row.tenant_id ||
                          row.tenant_id === read.filters.find(([key]) => key === 'tenant_id')?.[1],
                      )
                    : table === 'bot_settings'
                      ? {
                          ai_instructions:
                            savedRules && typeof savedRules === 'object'
                              ? savedRules[read.filters.find(([key]) => key === 'tenant_id')?.[1]]
                              : savedRules,
                        }
                      : [],
            error:
              (error && table === 'bot_settings') || (savedError && table === 'inbox_quick_replies')
                ? { code: 'DB_DOWN' }
                : null,
          }).then(resolve, reject)
        },
      }
      return q
    },
  }
  return {
    api,
    db,
    reads,
    writes,
    run: (tenantId = 'own') =>
      api.prepareAgentGeneration(
        db,
        { tenantId, customerId: '', instructions: 'caller-supplied stale fee 999' },
        'ค่าส่งเท่าไหร่',
      ),
    setRules: (value) => (savedRules = value),
    setSaved: (value) => (savedRows = value),
    reserves: () => reserves,
  }
}
test('AI context includes the full active catalog across pages and stored knowledge sources', async () => {
  const catalog = Array.from({ length: 205 }, (_, i) => ({
    code: `P${i}`,
    name: `Product ${i}`,
    price: 10,
    stock: 2,
    description: 'Product details',
  }))
  const f = fixture({
    rules: null,
    catalog,
    knowledge: [
      {
        id: 'faq-one',
        kind: 'faq',
        title: 'FAQ',
        content: 'Shop opening hours 09:00',
        is_active: true,
      },
    ],
  })
  const control = await f.run()
  assert.equal(control.products.length, 205)
  assert.match(control.systemInstruction, /P204/)
  assert.match(control.systemInstruction, /Shop opening hours 09:00/)
  assert.equal(f.reads.filter((read) => read.table === 'products').length, 3)
})

test('catalog context includes image URLs and grounded image replies use stored details or a polite no-match', async () => {
  const product = {
    code: 'IMG1',
    name: 'Blue bag',
    price: 250,
    stock: 3,
    description: 'Canvas bag with zip closure',
    image_url: 'https://storage.example.test/main.webp',
    commerce_images: [
      'https://storage.example.test/main.webp',
      'https://storage.example.test/detail.webp',
    ],
  }
  const f = fixture({ rules: null, catalog: [product] })
  const control = await f.run()
  assert.match(control.systemInstruction, /main.webp/)
  assert.match(control.systemInstruction, /detail.webp/)
  const answer = core.groundedAgentReply(
    JSON.stringify({ decision: 'ANSWER', knowledgeIds: [], productCodes: ['IMG1'] }),
    [],
    [product],
    undefined,
    true,
  )
  assert.match(answer.text, /Blue bag/)
  assert.match(answer.text, /250.00/)
  assert.match(answer.text, /Canvas bag/)
  const missing = core.groundedAgentReply(
    JSON.stringify({ decision: 'CLARIFY', knowledgeIds: [], productCodes: [] }),
    [],
    [product],
    undefined,
    true,
  )
  assert.equal(missing.text, core.IMAGE_PRODUCT_NOT_FOUND)
  assert.equal(missing.handoff, false)
  assert.equal(
    core.groundedAgentReply(JSON.stringify({ decision: 'HANDOFF' }), [], [product], undefined, true)
      .handoff,
    true,
  )
})

test('manual saved replies enter backend knowledge with exact bank details and tenant isolation', async () => {
  const own = {
    id: 'bank',
    tenant_id: 'own',
    shortcut: 'เลขบัญชี',
    body: 'ธนาคารทดสอบ เลขบัญชี 0123456789 ชื่อบัญชี ร้านทดสอบ',
  }
  const f = fixture({
    rules: null,
    saved: [
      own,
      { id: 'foreign', tenant_id: 'other', shortcut: 'Foreign', body: 'Other shop only' },
    ],
  })
  const control = await f.run()
  assert.match(control.systemInstruction, /0123456789/)
  assert.doesNotMatch(control.systemInstruction, /Other shop only/)
  assert.ok(
    f.reads.some(
      (read) =>
        read.table === 'inbox_quick_replies' &&
        read.filters.some(([key, value]) => key === 'tenant_id' && value === 'own'),
    ),
  )
  assert.match(control.systemInstruction, /without requiring an exact keyword/)
  const answer = await f.api.finishAgentGeneration(
    f.db,
    control,
    JSON.stringify({ decision: 'ANSWER', knowledgeIds: ['saved-reply:bank'], productCodes: [] }),
  )
  assert.equal(answer, own.body)
  assert.deepEqual(Array.from(f.writes[0].source_ids), ['saved-reply:bank'])
  f.setSaved([{ ...own, body: 'เลขบัญชีใหม่ 0987654321' }])
  const edited = await f.run()
  assert.match(edited.systemInstruction, /0987654321/)
  assert.doesNotMatch(edited.systemInstruction, /0123456789/)
  f.setSaved([])
  const deleted = await f.run()
  assert.equal(deleted.knowledge.length, 0)
  assert.equal(
    await f.api.finishAgentGeneration(
      f.db,
      deleted,
      '{"decision":"ANSWER","knowledgeIds":["saved-reply:bank"],"productCodes":[]}',
    ),
    '[HANDOVER]',
  )
})

